    try:
        yield session
    finally:
        session.close()


def create_relational_schema(url: str | None = None) -> None:
    Base.metadata.create_all(get_engine(url))


def reset_database_caches() -> None:
    get_engine.cache_clear()
    get_session_factory.cache_clear()

