### Fetch Paginated OHLCV Data from Gate.io (Python)

Source: https://github.com/ccxt/ccxt/wiki/examples/py/gate-fetch-ohlcv-pagination

This Python script uses the CCXT library to fetch historical OHLCV data for a specified symbol and timeframe from Gate.io. It includes a pagination loop to continuously fetch data until no more is available from the 'since' timestamp, updating the 'since' parameter for subsequent requests.

```python
# -*- coding: utf-8 -*-

import os
import sys


import ccxt  # noqa: E402


def table(values):
    first = values[0]
    keys = list(first.keys()) if isinstance(first, dict) else range(0, len(first))
    widths = [max([len(str(v[k])) for v in values]) for k in keys]
    string = ' | '.join(['{:<' + str(w) + '}' for w in widths])
    return "\n".join([string.format(*[str(v[k]) for k in keys]) for v in values])


def main():
    exchange = ccxt.gate()
    markets = exchange.load_markets()
    # exchange.verbose = True  # uncomment for debugging purposes if necessary
    since = exchange.parse8601('2022-01-01T00:00:00Z')
    symbol = 'BTC/USDT'
    timeframe = '1h'
    all_ohlcvs = []
    while True:
        try:
            ohlcvs = exchange.fetch_ohlcv(symbol, timeframe, since)
            all_ohlcvs += ohlcvs
            if len(ohlcvs):
                print('Fetched', len(ohlcvs), symbol, timeframe, 'candles from', exchange.iso8601(ohlcvs[0][0]))
                since = ohlcvs[-1][0] + 1
            else:
                break
        except Exception as e:
            print(type(e).__name__, str(e))
    print('Fetched', len(all_ohlcvs), symbol, timeframe, 'candles in total')
    if len(all_ohlcvs):
        print(table([[exchange.iso8601(o[0])] + o[1:] for o in all_ohlcvs]))


main()
